import { randomBytes } from 'node:crypto';
import { normalizeNetwork } from './contract-address.js';

const SUPPORTED_ACTIONS = new Set(['initialize_survey', 'cast_anonymous_vote']);

/**
 * Local-demo activity is named and generated by the server. It is deliberately
 * not a transaction hash and must never be displayed as a chain confirmation.
 */
export function createActivityReference(network, action) {
  const normalizedNetwork = normalizeNetwork(network);
  if (!normalizedNetwork) throw new Error('Unsupported Midnight network.');
  if (!SUPPORTED_ACTIONS.has(action)) throw new Error('Unsupported demo activity.');

  return {
    activityReference: `aura_demo_${normalizedNetwork}_${randomBytes(16).toString('hex')}`,
    network: normalizedNetwork,
    action,
    status: 'DEMO',
    createdAt: new Date().toISOString(),
  };
}

function sendJson(response, statusCode, body) {
  response.setHeader('Cache-Control', 'no-store, max-age=0');
  response.setHeader('Content-Type', 'application/json; charset=utf-8');
  if (typeof response.status === 'function') return response.status(statusCode).json(body);
  response.statusCode = statusCode;
  response.end(JSON.stringify(body));
  return undefined;
}

export default function handler(request, response) {
  if (request.method !== 'POST') {
    response.setHeader('Allow', 'POST');
    return sendJson(response, 405, { error: 'Method not allowed.' });
  }

  try {
    const body = typeof request.body === 'string' ? JSON.parse(request.body) : (request.body || {});
    return sendJson(response, 200, createActivityReference(body.network, body.action));
  } catch (error) {
    return sendJson(response, 400, { error: error.message || 'Invalid activity request.' });
  }
}
